B.bcA=new A.r9("Was ist ein Snapshot?","info",B.d7,B.c_p,null)
B.b6G=new A.jM("event",B.h8,"Jahresabschluss",'F\xfcr den Stichtag 31.12. eines Jahres. Wird automatisch mit dem Titel "Jahresabschluss [Jahr]" angelegt.',null,null)
B.b6F=new A.jM("event_note",B.B0,"Quartalsabschluss",'F\xfcr ein Quartal \u2014 z.B. "Q3 2025". Das richtige Quartal wird aus dem Stichtag automatisch ermittelt.',null,null)
B.b6K=new A.jM("fact_check",B.B1,"Inventur",'Beliebiger Stichtag f\xfcr eine Bestandspr\xfcfung. Wird mit Datum betitelt: "Inventur 15.08.2025".',null,null)
